import type { Entity } from '../entities/entity.js';
export interface EntityGateway { find(id: string): Promise<Entity | undefined> }
export interface EntityOutput { present(entity: Entity | undefined): void }
export class FindEntity {
  constructor(private readonly gateway: EntityGateway, private readonly output: EntityOutput) {}
  async execute(id: string): Promise<void> { this.output.present(await this.gateway.find(id)); }
}

