import type { Entity } from '../../entities/entity.js';
import type { EntityOutput } from '../../use-cases/find-entity.js';
export class EntityPresenter implements EntityOutput {
  model: { id: string } | undefined;
  present(entity: Entity | undefined): void { this.model = entity ? { id: entity.id } : undefined; }
}

