import type { Entity } from '../model/entity.js';
export class EntityStore {
  private readonly entries = new Map<string, Entity>();
  find(id: string): Entity | undefined { return this.entries.get(id); }
  save(entity: Entity): void { this.entries.set(entity.id, entity); }
}

